(()=>{"use strict";new class{constructor(){this.icon=document.querySelector(".site-header__menu-icon"),this.nav=document.querySelector(".site-header__menu-content"),this.siteHeader=document.querySelector(".site-header"),this.events()}events(){this.icon.addEventListener("click",(()=>this.toggleTheMenu()))}toggleTheMenu(){this.nav.classList.toggle("site-header__menu-content--is-visible"),this.siteHeader.classList.toggle("site-header--is-expanded"),this.icon.classList.toggle("site-header__menu-icon--close-x")}}})();